// 轻量级 Markdown 解析器
(function(global) {
  'use strict';

  function escapeHtml(text) {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function parseMarkdown(text) {
    if (!text) return '';

    let html = text;

    // 转义 HTML 特殊字符（除了代码块中的内容）
    // 先处理代码块
    const codeBlocks = [];
    html = html.replace(/```([\s\S]*?)```/g, function(match, code) {
      codeBlocks.push('<pre><code>' + escapeHtml(code.trim()) + '</code></pre>');
      return '\x00CODE' + (codeBlocks.length - 1) + '\x00';
    });

    // 处理行内代码
    const inlineCodes = [];
    html = html.replace(/`([^`]+)`/g, function(match, code) {
      inlineCodes.push('<code>' + escapeHtml(code) + '</code>');
      return '\x00INLINE' + (inlineCodes.length - 1) + '\x00';
    });

    // 处理表格
    const tables = [];
    html = html.replace(/((?:^\|[^\n]*\|\n)+)/gm, function(match, tableContent) {
      const lines = tableContent.trim().split('\n');
      if (lines.length < 2) return match;

      // 检查第二行是否是分隔符行 (|------|------|)
      const separatorLine = lines[1].trim();
      if (!separatorLine.match(/^\|[-:\s|]+\|$/)) return match;

      let tableHtml = '<table>';

      // 处理表头
      const headers = lines[0].split('|').map(s => s.trim()).filter(s => s);
      tableHtml += '<thead><tr>';
      headers.forEach(header => {
        tableHtml += '<th>' + escapeHtml(header) + '</th>';
      });
      tableHtml += '</tr></thead>';

      // 处理表身
      tableHtml += '<tbody>';
      for (let i = 2; i < lines.length; i++) {
        const cells = lines[i].split('|').map(s => s.trim()).filter(s => s);
        if (cells.length > 0) {
          tableHtml += '<tr>';
          cells.forEach(cell => {
            tableHtml += '<td>' + escapeHtml(cell) + '</td>';
          });
          tableHtml += '</tr>';
        }
      }
      tableHtml += '</tbody></table>';

      tables.push(tableHtml);
      return '\x00TABLE' + (tables.length - 1) + '\x00';
    });

    // 处理标题
    html = html.replace(/^###### (.*$)/gim, '<h6>$1</h6>');
    html = html.replace(/^##### (.*$)/gim, '<h5>$1</h5>');
    html = html.replace(/^#### (.*$)/gim, '<h4>$1</h4>');
    html = html.replace(/^### (.*$)/gim, '<h3>$1</h3>');
    html = html.replace(/^## (.*$)/gim, '<h2>$1</h2>');
    html = html.replace(/^# (.*$)/gim, '<h1>$1</h1>');

    // 处理粗体
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/__([^_]+)__/g, '<strong>$1</strong>');

    // 处理斜体
    html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    html = html.replace(/_([^_]+)_/g, '<em>$1</em>');

    // 处理删除线
    html = html.replace(/~~([^~]+)~~/g, '<del>$1</del>');

    // 处理链接
    html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank">$1</a>');

    // 处理图片
    html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img alt="$1" src="$2" style="max-width:100%;">');

    // 处理引用块
    html = html.replace(/^\> (.*$)/gim, '<blockquote>$1</blockquote>');

    // 处理无序列表
    html = html.replace(/^\* (.*$)/gim, '<li>$1</li>');
    html = html.replace(/^- (.*$)/gim, '<li>$1</li>');

    // 将连续的 li 包裹在 ul 中
    html = html.replace(/(<li>.*<\/li>)(\n<li>.*<\/li>)*/g, function(match) {
      return '<ul>' + match + '</ul>';
    });

    // 处理有序列表
    html = html.replace(/^\d+\. (.*$)/gim, '<li>$1</li>');

    // 处理分隔线
    html = html.replace(/^---$/gim, '<hr>');
    html = html.replace(/^\*\*\*$/gim, '<hr>');
    html = html.replace(/^___$/gim, '<hr>');

    // 处理段落（在行之间添加 p 标签）
    const lines = html.split('\n');
    const result = [];
    let inParagraph = false;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();

      if (!line) {
        if (inParagraph) {
          result.push('</p>');
          inParagraph = false;
        }
        continue;
      }

      // 如果行已经是块级元素，不包裹在 p 中
      if (line.match(/^<(h[1-6]|ul|ol|li|blockquote|pre|hr)/)) {
        if (inParagraph) {
          result.push('</p>');
          inParagraph = false;
        }
        result.push(line);
      } else if (line.match(/<\/(h[1-6]|ul|ol|li|blockquote|pre|hr)>$/)) {
        result.push(line);
        inParagraph = false;
      } else {
        if (!inParagraph) {
          result.push('<p>');
          inParagraph = true;
        }
        result.push(line);
      }
    }

    if (inParagraph) {
      result.push('</p>');
    }

    html = result.join('\n');

    // 替换代码块占位符
    html = html.replace(/\x00CODE(\d+)\x00/g, function(match, index) {
      return codeBlocks[parseInt(index)];
    });

    // 替换表格占位符
    html = html.replace(/\x00TABLE(\d+)\x00/g, function(match, index) {
      return tables[parseInt(index)];
    });

    // 替换行内代码占位符
    html = html.replace(/\x00INLINE(\d+)\x00/g, function(match, index) {
      return inlineCodes[parseInt(index)];
    });

    return html;
  }

  // 暴露 API
  const marked = {
    parse: function(text, options) {
      return parseMarkdown(text);
    },
    parseInline: function(text) {
      return parseMarkdown(text);
    },
    setOptions: function(options) {
      // 为了保持兼容，接受设置但暂时不使用
    }
  };

  // 导出
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = marked;
  } else if (typeof define === 'function' && define.amd) {
    define(function() { return marked; });
  } else {
    global.marked = marked;
  }

})(typeof globalThis !== 'undefined' ? globalThis : typeof window !== 'undefined' ? window : this);
